package dev.phonepad;

import android.app.*;
import android.content.Context;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.util.*;

/** Reusable definitions and assignment controls, backed by the layout's normal history. */
final class MacroLibrary {
    static void render(PadView pad,FrameLayout host,Runnable refresh){
        pad.config.ensureBuiltinMacros();Context c=pad.getContext();pad.config.migrateMacros();int inset=EditorStyle.dp(c,12);LinearLayout root=EditorStyle.column(c);root.setPadding(inset,inset,inset,0);host.addView(root,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout bar=new LinearLayout(c);root.addView(bar);EditText search=new EditText(c);search.setSingleLine();search.setHint("Find a macro");search.setTextColor(EditorStyle.TEXT);search.setHintTextColor(EditorStyle.MUTED);bar.addView(search,new LinearLayout.LayoutParams(0,EditorStyle.dp(c,48),1));EditorStyle.add(bar,EditorStyle.button(c,"＋ Create macro",true,()->create(pad,"",refresh)),150,44);
        ScrollView scroll=new ScrollView(c);scroll.setClipToPadding(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));GridLayout grid=new GridLayout(c);grid.setPadding(0,EditorStyle.dp(c,6),0,inset);scroll.addView(grid);
        Runnable draw=()->{grid.removeAllViews();int cols=Math.max(1,Math.min(3,c.getResources().getConfiguration().screenWidthDp/300));grid.setColumnCount(cols);String filter=search.getText().toString().toLowerCase(Locale.ROOT);int count=0;
            for(ControllerConfig.Macro m:pad.config.macros){if(!m.name.toLowerCase(Locale.ROOT).contains(filter))continue;count++;LinearLayout card=EditorStyle.column(c);int cardInset=EditorStyle.dp(c,14);card.setPadding(cardInset,cardInset,cardInset,cardInset);card.setBackground(EditorStyle.background(c,EditorStyle.PANEL));card.addView(EditorStyle.text(c,m.name+(m.builtin.isEmpty()?"":"  ·  built-in"),16,EditorStyle.TEXT));
                TextView previewTitle=EditorStyle.text(c,"ACTION PREVIEW",10,EditorStyle.MUTED);LinearLayout.LayoutParams titleLp=new LinearLayout.LayoutParams(-1,EditorStyle.dp(c,24));titleLp.topMargin=EditorStyle.dp(c,6);card.addView(previewTitle,titleLp);
                View sequence=InputTokens.sequence(c,m.program);sequence.setBackground(EditorStyle.background(c,EditorStyle.SURFACE));sequence.setContentDescription("Macro preview: "+m.program.replace('\n',';'));card.addView(sequence,new LinearLayout.LayoutParams(-1,EditorStyle.dp(c,52)));
                StringJoiner assigned=new StringJoiner(", ");Set<String> triggers=new LinkedHashSet<>();for(ControllerConfig.MacroAssignment a:pad.config.macroAssignments)if(a.macroId.equals(m.id)){ControllerConfig.Control control=pad.config.get(a.controlId);if(control!=null)assigned.add(control.title());triggers.add(triggerName(a.trigger));}
                card.addView(EditorStyle.text(c,Automation.stepCount(m.program)+" steps · "+(triggers.isEmpty()?"Unassigned":String.join(" / ",triggers))+"\n"+(assigned.length()==0?"No controls assigned":assigned.toString()),12,EditorStyle.MUTED));
                LinearLayout actions=new LinearLayout(c);card.addView(actions);EditorStyle.add(actions,EditorStyle.button(c,"Open / Edit",true,()->MacroEditor.showMacro(pad,m.id,refresh)),104,44);EditorStyle.add(actions,EditorStyle.button(c,m.enabled?"Enabled":"Disabled",m.enabled,()->pad.requestLayoutEdit(()->{pad.mutate(()->pad.config.macro(m.id).enabled=!m.enabled);refresh.run();},()->{})),90,44);EditorStyle.add(actions,EditorStyle.button(c,"⋮",false,()->options(pad,m.id,refresh)),44,44);
                GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=0;lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);int gap=EditorStyle.dp(c,6);lp.setMargins(gap,gap,gap,gap);grid.addView(card,lp);
            }
            if(count==0)grid.addView(EditorStyle.text(c,filter.isEmpty()?"Create your first sequence\n[ A ↓ ] → [ 100 ms ] → [ A ↑ ]\nAssign it to one or more controls.":"No matching macros",16,EditorStyle.MUTED));
        };search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){draw.run();}public void afterTextChanged(Editable e){}});draw.run();
    }
    static String triggerName(String value){switch(value){case "HOLD":return "While held";case "TOGGLE":return "Toggle";case "TAP":return "Tap";case "DOUBLE_TAP":return "Double tap";case "LONG_PRESS":return "Long press";default:return "Once";}}
    static String preview(String program){StringJoiner out=new StringJoiner(" → ");int count=0;for(String line:program.split("\n")){if(line.trim().isEmpty()||line.startsWith("#"))continue;if(count++==4){out.add("…");break;}out.add("[ "+line.replace("press ","↓ ").replace("release ","↑ ").replace("wait ","◷ ").replace("KEY_","").replace("MOUSE_","Mouse ")+" ]");}return count==0?"＋ Add your first action":out.toString();}
    static void create(PadView pad,String control,Runnable done){pad.requestLayoutEdit(()->{ControllerConfig.Macro m=new ControllerConfig.Macro();pad.mutate(()->{pad.config.macros.add(m);if(!control.isEmpty())pad.config.assign(m.id,control,"PRESS");});MacroEditor.showMacro(pad,m.id,done);},()->{});}
    static void rename(PadView pad,String id,Runnable done){EditText field=new EditText(pad.getContext());field.setSingleLine();field.setText(pad.config.macro(id).name);new AlertDialog.Builder(pad.getContext()).setTitle("Macro name").setView(field).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String value=field.getText().toString().trim();if(!value.isEmpty())pad.requestLayoutEdit(()->{pad.mutate(()->pad.config.macro(id).name=value.substring(0,Math.min(80,value.length())));done.run();},()->{});}).show();}
    static void options(PadView pad,String id,Runnable done){ControllerConfig.Macro macro=pad.config.macro(id);String[] items=macro!=null&&!macro.builtin.isEmpty()?new String[]{"Rename","Assign controls","Duplicate"}:new String[]{"Rename","Assign controls","Duplicate","Delete"};new AlertDialog.Builder(pad.getContext()).setItems(items,(d,n)->{if(n==0)rename(pad,id,done);if(n==1)assignments(pad,id,done);if(n==2)pad.requestLayoutEdit(()->{pad.mutate(()->pad.config.duplicateMacro(id));done.run();},()->{});if(n==3)new AlertDialog.Builder(pad.getContext()).setTitle("Delete macro and its assignments?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(a,b)->pad.requestLayoutEdit(()->{pad.mutate(()->pad.config.deleteMacro(id));done.run();},()->{})).show();}).show();}
    static void assignments(PadView pad,String id,Runnable done){pad.config.ensureBuiltinMacros();ArrayList<ControllerConfig.Control> controls=new ArrayList<>();for(ControllerConfig.Control c:pad.config.controls)if(AutomationEditor.mappable(c))controls.add(c);String[] names=new String[controls.size()];for(int i=0;i<names.length;i++)names[i]=controls.get(i).title();new AlertDialog.Builder(pad.getContext()).setTitle("Add control assignment").setItems(names,(d,n)->trigger(pad,id,mode->{pad.requestLayoutEdit(()->{pad.mutate(()->pad.config.assign(id,controls.get(n).id,mode));done.run();},()->{});})).show();}
    static void trigger(PadView pad,java.util.function.Consumer<String> done){trigger(pad,"",done);}
    static void trigger(PadView pad,String macroId,java.util.function.Consumer<String> done){ControllerConfig.Macro macro=pad.config.macro(macroId);boolean steering=macro!=null&&Automation.containsSteer(macro.program);String[] modes=steering?new String[]{"HOLD"}:new String[]{"PRESS","HOLD","TOGGLE","TAP","DOUBLE_TAP","LONG_PRESS"};String[] labels=new String[modes.length];for(int i=0;i<modes.length;i++)labels[i]=triggerName(modes[i]);new AlertDialog.Builder(pad.getContext()).setTitle(steering?"Steering runs while held":"Trigger").setItems(labels,(d,n)->done.accept(modes[n])).show();}
    static void attached(PadView pad,LinearLayout body,String control,Runnable refresh){
        pad.config.ensureBuiltinMacros();Context c=pad.getContext();body.addView(EditorStyle.text(c,"Macros",13,EditorStyle.MUTED));
        for(ControllerConfig.MacroAssignment a:new ArrayList<>(pad.config.macroAssignments))if(a.controlId.equals(control)){
            ControllerConfig.Macro m=pad.config.macro(a.macroId);if(m==null)continue;
            body.addView(EditorStyle.button(c,m.name+" · "+triggerName(a.trigger),false,()->MacroEditor.showMacro(pad,m.id,refresh)));body.addView(InputTokens.sequence(c,m.program));
            LinearLayout row=new LinearLayout(c);body.addView(row);EditorStyle.add(row,EditorStyle.button(c,a.enabled?"On":"Off",a.enabled,()->{pad.mutate(()->{for(ControllerConfig.MacroAssignment live:pad.config.macroAssignments)if(live.id.equals(a.id))live.enabled=!a.enabled;});refresh.run();}),48,44);EditorStyle.add(row,EditorStyle.button(c,"⋮",false,()->new AlertDialog.Builder(c).setItems(new String[]{"Change trigger","Duplicate macro","Remove assignment"},(d,n)->{if(n==0)trigger(pad,m.id,mode->{pad.mutate(()->{for(ControllerConfig.MacroAssignment live:pad.config.macroAssignments)if(live.id.equals(a.id))live.trigger=mode;});refresh.run();});if(n==1){pad.mutate(()->{ControllerConfig.Macro copy=pad.config.duplicateMacro(m.id);pad.config.assign(copy.id,control,a.trigger);});refresh.run();}if(n==2){pad.mutate(()->pad.config.macroAssignments.removeIf(live->live.id.equals(a.id)));refresh.run();}}).show()),48,44);
        }
        body.addView(EditorStyle.button(c,"＋ New macro",true,()->create(pad,control,refresh)));
        body.addView(EditorStyle.button(c,"Connect existing macro",false,()->{String[] names=new String[pad.config.macros.size()];for(int i=0;i<names.length;i++)names[i]=pad.config.macros.get(i).name;new AlertDialog.Builder(c).setItems(names,(d,n)->{String id=pad.config.macros.get(n).id;trigger(pad,id,mode->{pad.mutate(()->pad.config.assign(id,control,mode));refresh.run();});}).show();}));
    }
}
